static void p256_reverse(uint8_t *v) {
    for (int i = 0; i < p256_element_length / 2; i++) {
        uint8_t t = v[i];
        v[i] = v[p256_element_length - 1 - i];
        v[p256_element_length - 1 - i] = t;
    }
}

