/* Writes the 32 byte big endian encoding of e to out. */
static void p256_bytes(const NistecP256Element *e, uint8_t *out) {
    fiat_p256_non_montgomery_domain_field_element tmp;
    fiat_p256_from_montgomery(tmp, e->l);
    fiat_p256_to_bytes(out, tmp);
    p256_reverse(out);
}

static void p256_from_canonical_bytes(NistecP256Element *e, const uint8_t *in) {
    fiat_p256_non_montgomery_domain_field_element tmp;
    fiat_p256_from_bytes(tmp, in);
    fiat_p256_to_montgomery(e->l, tmp);
}

static int p256_equal(const NistecP256Element *e, const NistecP256Element *t) {
    uint8_t eb[p256_element_length], tb[p256_element_length];
    p256_bytes(e, eb);
    p256_bytes(t, tb);
    return burrow__nistec_equal_bytes(eb, tb, p256_element_length);
}

static int p256_is_zero(const NistecP256Element *e) {
    uint8_t eb[p256_element_length], zero[p256_element_length];
    memset(zero, 0, sizeof zero);
    p256_bytes(e, eb);
    return burrow__nistec_equal_bytes(eb, zero, p256_element_length);
}

/* Sets e to the value of the 32 big endian bytes at v. Go's SetBytes also
 * takes a slice of the wrong length, which nothing here passes it. */
static NistecP256Element *p256_set_bytes(NistecP256Element *e, const uint8_t *v,
                                         Error *err) {
    /* Check for non-canonical encodings (p + k, 2p + k, etc.) by comparing to
     * the encoding of -1 mod p, so p - 1, the highest canonical encoding. */
    NistecP256Element zero, one, minus_one;
    uint8_t minus_one_encoding[p256_element_length];
    memset(&zero, 0, sizeof zero);
    p256_bytes(p256_sub(&minus_one, &zero, p256_one(&one)), minus_one_encoding);
    if (burrow__nistec_less_or_eq_bytes(v, minus_one_encoding, p256_element_length) ==
        0) {
        BURROW_OUT(err, errors_new(error_allocator(),
                                   BURROW_S("invalid P256Element encoding")));
        return NULL;
    }
    uint8_t in[p256_element_length];
    memcpy(in, v, sizeof in);
    p256_reverse(in);
    p256_from_canonical_bytes(e, in);
    return e;
}

/* Sets v to a if cond is 1 and to b if cond is 0. */
static NistecP256Element *p256_select(NistecP256Element *v, const NistecP256Element *a,
                                      const NistecP256Element *b, int cond) {
    fiat_p256_selectznz(v->l, (fiat_p256_uint1)cond, b->l, a->l);
    return v;
}

/* Sets e to 1/x and returns e. If x is 0, the result is 0. Inversion is
 * exponentiation by p - 2. */
static NistecP256Element *p256_invert(NistecP256Element *e,
                                      const NistecP256Element *x) {
    NistecP256Element z_, t0_, t1_;
    NistecP256Element *z = &z_, *t0 = &t0_, *t1 = &t1_;
    /* Inversion is implemented as exponentiation with exponent p − 2.
     * The sequence of 12 multiplications and 255 squarings is derived from the
     * following addition chain generated with github.com/mmcloughlin/addchain v0.4.0.
     *
     * _10     = 2*1
     * _11     = 1 + _10
     * _110    = 2*_11
     * _111    = 1 + _110
     * _111000 = _111 << 3
     * _111111 = _111 + _111000
     * x12     = _111111 << 6 + _111111
     * x15     = x12 << 3 + _111
     * x16     = 2*x15 + 1
     * x32     = x16 << 16 + x16
     * i53     = x32 << 15
     * x47     = x15 + i53
     * i263    = ((i53 << 17 + 1) << 143 + x47) << 47
     * return    (x47 + i263) << 2 + 1 */
    p256_square(z, x);
    p256_mul(z, x, z);
    p256_square(z, z);
    p256_mul(z, x, z);
    p256_square(t0, z);
    for (int s = 1; s < 3; s++)
        p256_square(t0, t0);
    p256_mul(t0, z, t0);
    p256_square(t1, t0);
    for (int s = 1; s < 6; s++)
        p256_square(t1, t1);
    p256_mul(t0, t0, t1);
    for (int s = 0; s < 3; s++)
        p256_square(t0, t0);
    p256_mul(z, z, t0);
    p256_square(t0, z);
    p256_mul(t0, x, t0);
    p256_square(t1, t0);
    for (int s = 1; s < 16; s++)
        p256_square(t1, t1);
    p256_mul(t0, t0, t1);
    for (int s = 0; s < 15; s++)
        p256_square(t0, t0);
    p256_mul(z, z, t0);
    for (int s = 0; s < 17; s++)
        p256_square(t0, t0);
    p256_mul(t0, x, t0);
    for (int s = 0; s < 143; s++)
        p256_square(t0, t0);
    p256_mul(t0, z, t0);
    for (int s = 0; s < 47; s++)
        p256_square(t0, t0);
    p256_mul(z, z, t0);
    for (int s = 0; s < 2; s++)
        p256_square(z, z);
    p256_mul(z, x, z);

    *e = *z;
    return e;
}

/* Sets e to the square of x, n times over, for n of at least 1. */
static void p256_square_n(NistecP256Element *e, const NistecP256Element *x, int n) {
    p256_square(e, x);
    for (int i = 1; i < n; i++)
        p256_square(e, e);
}

/* Sets e to a square root of x. If x is not a square, returns 0 and leaves e
 * unchanged. e and x can overlap. */
static int p256_sqrt(NistecP256Element *e, const NistecP256Element *x) {
    NistecP256Element t0_, t1_;
    NistecP256Element *t0 = &t0_, *t1 = &t1_;
    /* Since p = 3 mod 4, exponentiation by (p + 1) / 4 yields a square root candidate.
     *
     * The sequence of 7 multiplications and 253 squarings is derived from the
     * following addition chain generated with github.com/mmcloughlin/addchain v0.4.0.
     *
     * _10       = 2*1
     * _11       = 1 + _10
     * _1100     = _11 << 2
     * _1111     = _11 + _1100
     * _11110000 = _1111 << 4
     * _11111111 = _1111 + _11110000
     * x16       = _11111111 << 8 + _11111111
     * x32       = x16 << 16 + x16
     * return      ((x32 << 32 + 1) << 96 + 1) << 94 */
    p256_square_n(t0, x, 1);
    p256_mul(t0, x, t0);
    p256_square_n(t1, t0, 2);
    p256_mul(t0, t0, t1);
    p256_square_n(t1, t0, 4);
    p256_mul(t0, t0, t1);
    p256_square_n(t1, t0, 8);
    p256_mul(t0, t0, t1);
    p256_square_n(t1, t0, 16);
    p256_mul(t0, t0, t1);
    p256_square_n(t0, t0, 32);
    p256_mul(t0, x, t0);
    p256_square_n(t0, t0, 96);
    p256_mul(t0, x, t0);
    p256_square_n(t0, t0, 94);

    /* Check if the candidate t0 is indeed a square root of x. */
    p256_square(t1, t0);
    if (p256_equal(t1, x) != 1)
        return 0;
    *e = *t0;
    return 1;
}

